import {alternatives} from './variants.mjs';
import {bank,code,starter,execute} from './bank.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'null').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),json=v=>JSON.stringify(v),statuses=['Not Started','Learning','Practiced','Solved Independently','Needs Revision','Mastered'];
let storageOK=true,saved;try{saved=JSON.parse(localStorage.getItem('sdet-lab-v1')||'{}');}catch{saved={};storageOK=false;}
let progress=saved.progress||{},days=saved.days||{},theme=saved.theme||'light',view='lab',topic='All topics',search='',difficulty='All levels',qid=location.hash.slice(1)||'A06',stage=2,mode='learn',step=0,playing=false,speed=1,inputIndex=0,custom=null,hints=0,revealed=false,showTraceCode=false,testOpen=false,selectedDay=1,sessionEnd=null,sessionDone=false,debugIndex=0,debugSubmitted=false,bugRevealed=false,research=null;
if(!bank.some(q=>q.id===qid))qid='A06';
let trace=execute(current(),current().samples[0]);
const topics=[...new Set(bank.map(q=>q.topic))];
function current(){return bank.find(q=>q.id===qid);}function entry(id=qid){return progress[id]||{status:'Not Started',seconds:0};}function persist(){try{localStorage.setItem('sdet-lab-v1',json({...saved,schemaVersion:1,progress,days,theme}));}catch{storageOK=false;}}function update(value,id=qid){progress[id]={...entry(id),...value};persist();}function toast(t){$('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),4000);}function navigate(v){view=v;playing=false;render();window.scrollTo(0,0);}function openQuestion(id,m='learn',st=0){qid=id;mode=m;stage=st;view='lab';inputIndex=0;custom=null;step=0;playing=false;hints=0;revealed=false;showTraceCode=false;testOpen=false;sessionEnd=null;sessionDone=false;trace=execute(current(),current().samples[0]);if(entry().status==='Not Started')update({status:'Learning'});history.replaceState(null,'','#'+qid);render();window.scrollTo(0,0);}
function locked(){return mode==='timed'&&!sessionDone&&!revealed;}
function highlight(s){let re=/("(?:\\.|[^"\\])*"|\/\/[^\n]*|\b(?:public|class|static|int|long|boolean|char|return|if|else|while|for|throw|new|import|void|null|true|false)\b|\b[0-9]+\b)/g;let out='',last=0;for(let m of s.matchAll(re)){out+=esc(s.slice(last,m.index));let t=m[0],c=t.startsWith('//')?'comment':t.startsWith('"')?'str':/^[0-9]/.test(t)?'num':'kw';out+='<span class="'+c+'">'+esc(t)+'</span>';last=m.index+t.length;}return out+esc(s.slice(last));}
function navbutton(label,icon,dest,count='',active=false){return `<button data-nav="${esc(dest)}" class="${active?'active':''}"><span class="navsymbol" aria-hidden="true">${icon}</span>${label}<span class="count">${count}</span></button>`;}
function sidebar(){let done=bank.filter(q=>['Solved Independently','Mastered'].includes(entry(q.id).status)).length;return `<aside class="sidebar"><div class="brand"><span class="brandmark">{j}</span><div>Java SDET<span style="display:block">Interview Lab</span><small>BUILD YOUR CODING INSTINCT</small></div></div><div class="nav"><div class="navlabel">YOUR WORKSPACE</div>${navbutton('Dashboard','◫','dashboard','',view==='dashboard')}${navbutton('Study roadmap','⌁','roadmap','21 days',view==='roadmap')}${navbutton('Question library','▤','library',bank.length,view==='library'&&topic==='All topics')}</div><div class="nav"><div class="navlabel">PRACTICE BY TOPIC</div>${topics.map((t,i)=>navbutton(t,['Aa','⌘','▥','▦','⇥','#','⌁','◇'][i]||'◇','topic:'+t,bank.filter(q=>q.topic===t).length,view==='library'&&topic===t)).join('')}</div><div class="nav">${navbutton('Debugging','⌘','debug','8',view==='debug')}${navbutton('Mock interview','◷','mock','',view==='mock')}${navbutton('Bookmarks','⚑','bookmarks',bank.filter(q=>entry(q.id).bookmark).length,view==='bookmarks')}${navbutton('Research & sources','↗','research','',view==='research')}</div><div class="sidefoot"><div class="row spread"><strong>Your interview toolkit</strong><span>${done}/${bank.length}</span></div><p>Small steps. Stronger problem solving.</p><div class="progress"><i style="width:${done/bank.length*100}%"></i></div><p>Self-reported independent completion</p></div></aside>`;}
function render(){document.body.classList.toggle('dark',theme==='dark');$('#app').innerHTML=`<div class="shell">${sidebar()}<div><header class="topbar"><button class="mobilemenu icon" data-action="menu" aria-label="Open navigation">☰</button><div class="crumb">Your workspace <span style="margin:0 10px">/</span> <b>${view==='lab'?'Coding practice':esc(({dashboard:'Dashboard',library:topic==='All topics'?'Question library':topic,roadmap:'Study roadmap',mock:'Mock interview',debug:'Debugging',research:'Research & sources',bookmarks:'Bookmarks'})[view])}</b></div><input class="search" aria-label="Search all questions" placeholder="Search questions…" value="${esc(search)}" id="globalSearch"><button class="icon ghost" data-action="theme" aria-label="Toggle light and dark theme">${theme==='light'?'☾':'☀'}</button><span class="avatar" aria-label="Your personal lab">SC</span></header><main class="content">${view==='lab'?lab():view==='dashboard'?dashboard():view==='library'||view==='bookmarks'?library():view==='roadmap'?roadmap():view==='mock'?mock():view==='debug'?debug():researchPage()}<footer class="footer"><span>JAVA SDET INTERVIEW LAB <span style="margin:0 8px">·</span> Built for the first two years.</span><span>Java 8 compatible solutions · Java 17 ready</span></footer></main></div></div>`;bind();}
function source(q){return `<div class="source">${esc(q.id)} · ${esc(q.source)}${q.url?` · <a href="${esc(q.url)}" target="_blank" rel="noreferrer">Source ↗</a> · Published ${esc(q.date)}`:' · No recent interview claim'}<br>Character algorithms use Java UTF-16 char units. Restrict visualizer inputs to ASCII for matching trace semantics.</div>`;}
function lab(){let q=current();return `<div class="titleline"><div><div class="eyebrow">${esc(q.topic)} / ${mode==='learn'?esc(q.pattern):'INDEPENDENT PRACTICE'}</div><h1>${esc(q.title)}</h1><div class="row"><span class="badge">${q.difficulty}</span><span class="badge outline">◷ ${q.time} min</span><span class="badge outline">${esc(q.id)}</span><small>Learn the pattern. Explain the why.</small></div></div><div class="row"><button data-action="bookmark">${entry().bookmark?'★ Bookmarked':'☆ Bookmark'}</button><button data-nav="library" class="ghost">All questions ↗</button></div></div><div class="modes" role="group" aria-label="Practice mode">${[['learn','◉ Learn with visualization'],['solve','⌨ Solve independently'],['timed','◷ Timed interview'],['debug','⌘ Debug a challenge']].map(([m,l])=>`<button class="${mode===m?'active':''}" data-mode="${m}">${l}</button>`).join('')}</div>${mode==='timed'?timerPanel():''}<div class="workspace"><section class="panel"><nav class="tabs" aria-label="Learning stages">${['Understand','Think','Visualize','Code','Explain & test'].map((l,i)=>`<button class="${stage===i?'active':''}" data-stage="${i}" ${locked()&&i!==0?'disabled':''}><span>${i+1}</span>${l}</button>`).join('')}</nav><div class="panelbody">${stage===0?understand(q):stage===1?think(q):stage===2?visualize(q):stage===3?approaches(q):explain(q)}${source(q)}</div></section><aside class="rightstack"><section class="panel codepanel"><div class="panelhead"><h3><span style="color:#abc191;margin-right:8px">☷</span> Solution.java</h3><span class="badge">JAVA 17 / 8+</span></div><div class="editor"><pre id="codeHighlight" aria-hidden="true">${highlight(entry().draft||starter(q))}</pre><textarea id="editor" aria-label="Java practice code" spellcheck="false" autocapitalize="off" autocomplete="off">${esc(entry().draft||starter(q))}</textarea></div><div class="editorfoot"><span>UTF-8 <span style="margin:0 8px">·</span> 4 spaces</span><span>Draft saved locally</span></div></section><section class="panel"><div class="panelhead"><h3>Your practice desk</h3><span class="badge outline">MANUAL REVIEW</span></div><div class="codeactions"><button data-action="resetCode">↺ Starter</button><button data-action="copy">Copy code</button><button data-action="download">↓ .java</button><button data-action="hint" ${locked()?'disabled':''}>Hint ${Math.min(hints+1,3)}/3</button><button data-action="reveal">${revealed?'View reference':'Reveal solution'}</button><button data-action="testHarness">↓ Test harness</button><button data-action="tests">${testOpen?'Hide':'Show'} tests</button></div><div class="panelbody" style="padding-top:0"><div class="notice"><strong>No Java compiler in this browser.</strong> Your submission is not executed or graded. Visuals simulate the reference algorithm. Download Solution.java and its test harness; run <code>javac Solution.java TestRunner.java &amp;&amp; java TestRunner</code> locally. Tests below show reference outputs only.</div>${testOpen?tests(q):''}</div></section><section class="panel"><div class="panelhead"><h3>Track your understanding</h3><span class="pillnum">${Math.floor((entry().seconds||0)/60)} min</span></div><div class="panelbody statusbox"><label for="status" class="muted" style="font-size:11px">Self-assessment · never an automated pass</label><select id="status">${statuses.map(s=>`<option ${entry().status===s?'selected':''}>${s}</option>`).join('')}</select><small style="font-size:10px;line-height:1.7">Choose “Mastered” after independently solving and explaining again on a later day. Viewing a reference never marks completion.</small>${entry().revisionDate?`<small>Next review: ${esc(entry().revisionDate)}</small>`:''}</div></section></aside></div>`;}
function understand(q){return `<div class="eyebrow">01 / Make the contract clear</div><h2>Your task</h2><p class="problem">${esc(statement(q))}</p><div class="example"><small>SAMPLE INPUT</small><br><code>${esc(json(q.samples[0]))}</code><br><small>EXPECTED OUTPUT</small><br><code>${esc(json(execute(q,q.samples[0]).result))}</code></div><h3 class="sectiongap">Constraints & edge cases</h3><p class="problem">Inputs match the types in <code>solve(${esc(q.param)})</code>. Null containers are rejected unless explicitly handled. Respect the preconditions below.</p><ul class="textlist">${q.edges.map(e=>`<li>${esc(e)}</li>`).join('')}<li>Visualizer: ASCII strings, at most 60 items or 120 characters; integer values must fit signed Java int.</li></ul>${mode==='learn'?`<h3>Why this matters in an interview</h3><p class="problem">${esc(q.qa||`This checks ${q.pattern.toLowerCase()} reasoning, clear loop boundaries, and your ability to choose and explain Java data structures. Useful foundation for junior QA/SDET automation tasks; no frequency claim is made.`)}</p>`:''}<button class="primary" data-stage="1" ${locked()?'disabled':''}>${mode==='learn'?'Think through the solution →':'Request thinking guidance →'}</button>`;}
function statement(q){const special={S01:'Return a new string with its characters in reverse order. Preserve case and whitespace.',S02:'Return true when the string reads identically from both ends; otherwise return false.',S04:'Return the occurrence count of every character, preserving first appearance order.',S06:'Return the first character that occurs exactly once. Return an empty string if none exists.',A01:'Reverse the supplied integer array in place and return the same array.',A03:'Return the second-largest distinct integer. Return null if fewer than two distinct values exist.',A05:'Given n distinct integers from 0 through n with exactly one missing, return the missing value. Input validity is a precondition.',A06:'Return the indices of two different elements whose mathematical sum equals target. Return an empty array when no pair exists. Return the first pair found by scanning left to right.',A07:'Move all zeros to the end in place, keeping the relative order of nonzero values.',A08:'Return a new array rotated k positions right. Negative k rotates left. Empty input returns empty.',A10:'Merge two ascending sorted arrays into a new ascending array, retaining duplicates.',A11:'On an ascending sorted array, return any matching target index, or -1 when absent.',Q04:'Return whether two flat maps have exactly the same keys and string values. Ignore insertion order.',B02:'Return the length of the longest contiguous substring with no repeated characters.'};const more={S03:'Count the English vowels a, e, i, o, u, ignoring case. Return the total number of occurrences.',S05:'Return each character that appears more than once, once per character, in first-appearance order.',S07:'Given exactly two non-null strings, return whether they contain exactly the same characters with the same counts. Case and spaces matter.',S08:'Reverse each literal-space-delimited word. Keep word positions and all literal spaces unchanged; tabs are part of a word.',S09:'Encode consecutive runs as a character followed by the run length, including length one. Return an empty string for empty input.',S10:'Count whitespace-delimited words after locale-independent lowercasing. Punctuation remains part of a word. Return counts in first-appearance order.',A02:'Return [minimum, maximum] from a nonempty integer array. Reject null or empty arrays.',A04:'Return distinct repeated integers, ordered by when each value is first detected as a duplicate.',A09:'Return each value present in both arrays once, ordered by its first occurrence in the second array.',A12:'Sort the array in place into ascending order. Keep duplicates.',M01:'Return a list containing each input value once, retaining its first-occurrence order.',M02:'Return the earliest integer that occurs exactly once in the full array. Return null if no such value exists.',M03:'Return a new map whose entries iterate in ascending natural string-key order. Keys must be non-null.',M04:'Return entries in descending count order. Resolve equal counts using ascending natural key order. Keys and values must be non-null.',C01:'Return a new list of non-null test names ordered by length, then by natural alphabetical order for equal lengths.',C02:'Return a copy with null, empty, and whitespace-only names removed. Retain the order of all other names.',C03:'Return a copied list of non-null TestResult objects ordered by ascending durationMs, then natural name order. Names must be non-null.',T01:'Return all exact FAIL statuses, retaining duplicates and order. Ignore nulls and other status values.',T02:'Return counts of each non-null status in encounter order. Include unknown statuses as separate groups.',T03:'Return a list of names transformed to uppercase using Locale.ROOT. Omit nulls and retain order.',N01:'Return whether n is prime: an integer at least two with no positive divisors other than one and itself.',N02:'Return the first n Fibonacci terms, starting with 0, 1. Accept n from 0 through 93 so every output term fits signed long.',N03:'Return n factorial as a long. Accept only 0 through 20; reject larger or negative inputs.',N04:'For integers 1 through n, return Fizz for multiples of 3, Buzz for multiples of 5, FizzBuzz for both, and the number otherwise. Accept 0 through 1000.',N05:'Return the sum of the decimal digits of the absolute mathematical value of n. Ignore the negative sign.',N06:'Return whether the decimal representation of n is a palindrome. Negative numbers are not palindromes.',Q01:'Given labels already extracted from a Selenium dropdown, return each repeated label once, in duplicate-detection order. Compare exact label text.',Q02:'Return the number of observations of each HTTP status code, in first-appearance order. Do not silently discard unusual codes.',Q03:'Count non-null log lines whose first whitespace-delimited token is exactly ERROR. In this exercise, every line starts with its level.',Q05:'Return duplicate API IDs once, in duplicate-detection order. Reject null or blank IDs. Compare IDs exactly.',Q06:'Return whether the entire ID matches TC- followed by exactly four ASCII digits. Null, spaces, and lowercase prefixes are invalid.',B01:'Return whether a string containing only ()[]{} has properly nested, matched brackets. Empty input is balanced; other characters are rejected.'};return special[q.id]||more[q.id];}
function hintText(q){return [`Start with this observation: ${q.idea.split('. ')[0]}.`,`Pattern to consider: ${q.pattern}. Track only the state needed for the next decision.`,`Walk through the sample by hand, update the state after each iteration, then use this contract: ${q.edges[0]}. Check your invariant before writing the return statement.`];}
function think(q){return `<div class="eyebrow">02 / Reason before you type</div><h2>Build a plan, one hint at a time.</h2><p class="problem">Restate the problem aloud. Choose the smallest input that exposes the main decision. Predict the result before opening the visualizer.</p><ol class="textlist"><li>What must the method return, and what can it change?</li><li>Which information do you need to remember between iterations?</li><li>When should the loop stop?</li></ol>${hintText(q).slice(0,hints).map((h,i)=>`<div class="hint"><strong>Hint ${i+1}</strong><br>${esc(h)}</div>`).join('')}<div class="row sectiongap"><button class="primary" data-action="hint" ${hints>=3?'disabled':''}>${hints>=3?'All hints revealed':'Reveal hint '+(hints+1)}</button><button data-stage="2">Visualize the idea →</button></div>`;}
function visualize(q){let s=trace.steps[step];return `<div class="row spread" style="margin-bottom:14px"><div><div class="eyebrow">03 / See the logic unfold</div><h2 style="margin-bottom:0">Inside the algorithm</h2></div><span class="badge outline">REFERENCE SIMULATION</span></div><div class="inputbar"><label for="sample">Input</label><select id="sample">${q.samples.map((v,i)=>`<option value="${i}" ${inputIndex===i&&custom===null?'selected':''}>${i+1}. ${esc(json(v))}</option>`).join('')}${custom!==null?'<option selected value="custom">Custom input</option>':''}</select><button data-action="custom" style="font-size:10px;padding:7px 9px">Edit JSON input</button></div><div class="visual" role="region" aria-label="Algorithm visualization"><div class="visualhead"><span>${esc(q.pattern)}</span><span>Step ${step} / ${trace.steps.length-1}</span></div>${s.cells.length?`<div class="cells">${s.cells.map((c,i)=>`<div class="cellwrap"><span class="pointer">${Object.entries(s.pointers).filter(([,v])=>v===i).map(([k])=>'↓ '+esc(k)).join(' ')||'&nbsp;'}</span><div class="cell ${s.active.includes(i)?'current':''}">${esc(c&&typeof c==='object'?c.name+':'+c.durationMs:c)}</div><span class="index">${i}</span></div>`).join('')}</div>`:'<div class="empty" style="padding:12px">Scalar state or empty sequence</div>'}${s.map.length?`<table class="maptable"><caption style="text-align:left;color:var(--muted);font-size:10px;padding-bottom:5px">DATA STRUCTURE · current contents</caption><thead><tr><th>Key / position</th><th>Value</th></tr></thead><tbody>${s.map.map(([k,v])=>`<tr class="${Object.values(s.vars).includes(k)?'hot':''}"><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table>`:''}<div class="vars">${Object.entries(s.vars).map(([k,v])=>`<span class="var">${esc(k)} <b>= ${esc(v)}</b></span>`).join('')}</div></div><div class="explanation" aria-live="polite"><span class="stepdot">${step}</span><span>${esc(s.explanation)}</span></div><div class="controls"><button data-action="play" class="primary">${playing?'⏸ Pause':'▶ Play'}</button><button data-action="previous" ${step===0?'disabled':''}>‹ Previous</button><button data-action="next" ${step===trace.steps.length-1?'disabled':''}>Next ›</button><button data-action="reset">↺ Reset</button><label class="speed" for="speed">Speed</label><select id="speed">${[.5,1,1.5,2].map(x=>`<option value="${x}" ${speed===x?'selected':''}>${x}×</option>`).join('')}</select></div><input class="timeline" id="timeline" type="range" aria-label="Execution step" min="0" max="${trace.steps.length-1}" value="${step}"><div class="row spread sectiongap"><h3 style="margin:0">Execution trace</h3><button data-action="traceCode" style="font-size:10px">${showTraceCode?'Hide traced Java':'Reveal traced Java'}</button></div>${showTraceCode?`<pre class="reference">${tracedCode(q,s)}</pre>`:''}<div class="tracewrap sectiongap"><table class="trace"><thead><tr><th>Step</th><th>Line</th><th>Variables</th><th>Data structure</th><th>Explanation</th></tr></thead><tbody>${trace.steps.map((t,i)=>`<tr class="${i===step?'selected':''}"><td><button data-step="${i}" aria-label="Go to step ${i}">${i}</button></td><td>${lineNo(q,t.line)||'—'}</td><td>${esc(Object.entries(t.vars).map(([k,v])=>k+'='+v).join(', '))}</td><td>${esc(json(t.map.length?t.map:t.cells))}</td><td>${esc(t.explanation)}</td></tr>`).join('')}</tbody></table></div><div class="notice">Each row is a meaningful state change, not every JVM instruction. Highlighted cells are current; unhighlighted cells are inactive. Hash operations use expected-time complexity. The trace shows reference output, never a result from your editor.</div>`;}
function lineNo(q,fragment){if(!fragment)return null;let lines=code(q).split('\n'),i=lines.findIndex(l=>l.trim().startsWith(fragment));if(i<0)i=lines.findIndex(l=>l.includes(fragment));return i<0?null:i+1;}function tracedCode(q,s){let n=lineNo(q,s.line);return code(q).split('\n').map((l,i)=>`<span class="${n===i+1?'executed':''}">${String(i+1).padStart(2,' ')}  ${esc(l)}</span>`).join('\n');}
function approaches(q){return `<div class="eyebrow">04 / Turn the idea into Java</div><h2>Write it before you reveal it.</h2><p class="problem">Use the starter signature in the practice desk. Explain your invariant, write the loop, then test the smallest boundary input.</p>${!revealed?'<button class="primary" data-action="reveal">Reveal reference & compare approaches</button>':`<div class="row spread"><h3>Reference · ${esc(q.pattern)}</h3><button data-action="copyReference">Copy reference</button></div><p class="problem">${esc(q.idea)}</p><pre class="reference">${highlight(code(q))}</pre><div class="row"><span class="badge outline">Time: ${esc(q.complexity)}</span><span class="badge outline">Space: ${esc(q.space)}</span></div>${alternatives[q.id]?`<h3 class="sectiongap">${esc(alternatives[q.id].name)}</h3><p class="problem">${esc(alternatives[q.id].trade)}</p><pre class="reference">${highlight(code({...q,body:alternatives[q.id].body}))}</pre><p class="problem">Time: ${esc(alternatives[q.id].time)} · Space: ${esc(alternatives[q.id].space)}</p>`:`<div class="notice">${comparison(q)}</div>`}<div class="notice">n = input length, m = second input length, k = distinct keys, f = matching failures. Output storage is included where stated. Java 8: use Collectors.toList(); Java 17 also supports Stream.toList(), whose returned list is unmodifiable.</div>`}`;}
function comparison(q){if(/map|set|membership|uniqueness/i.test(q.pattern))return 'Trade-off: a nested scan can reduce auxiliary collection storage but may take O(n²) time. This reference stores distinct keys to avoid rescanning the full prefix.';if(q.pattern==='Two pointers')return 'Trade-off: allocating a separate output sequence can simplify indexing but needs O(n) additional storage. Two pointers make the processed prefix and suffix explicit.';return 'The reference favors a direct implementation of this pattern. A second approach is not included where it would only restate the same algorithm; explain the stated time and storage costs before optimizing.';}
function tests(q){return `<div class="sectiongap"><div class="eyebrow">Reference cases · not submission results</div>${q.samples.map((s,i)=>`<div class="testcase"><span>CASE ${i+1} · <span class="muted">not run against your code</span></span><code>Input: ${esc(json(s))}</code><code>Expected: ${esc(json(execute(q,s).result))}</code></div>`).join('')}<p class="source">Long values in reference displays use decimal strings to preserve precision. In Java, factorial returns long and Fibonacci returns List&lt;Long&gt;.</p></div>`;}
function explain(q){return `<div class="eyebrow">05 / Explain, verify, reflect</div><h2>Make your reasoning interview ready.</h2><h3>Your 30–60 second explanation</h3>${revealed?`<div class="hint">“I would use ${esc(q.pattern.toLowerCase())}. ${esc(q.idea)} My time complexity is ${esc(q.complexity)} and my space complexity is ${esc(q.space)}. Before coding I would clarify ${esc(q.edges[0].toLowerCase())}. I would test the normal case, the smallest input, and a case that exercises the alternate branch.”</div>`:'<p class="problem">Rehearse: contract → approach → invariant → complexity → two edge tests. Reveal the reference when you want to compare your explanation.</p><button data-action="reveal">Reveal explanation & solution</button>'}<h3 class="sectiongap">Test it as a QA engineer</h3><ul class="textlist">${q.edges.map(e=>`<li>${esc(e)}</li>`).join('')}<li>Check a representative sample and a boundary input independently.</li><li>Assert the return value, output ordering, and whether the input is mutated.</li><li>For invalid data, verify the documented exception or precondition.</li></ul>${tests(q)}<h3 class="sectiongap">Common mistakes to avoid</h3><ul class="textlist"><li>${esc(mistake(q))}</li><li>Comparing String values with == instead of equals.</li><li>Ignoring empty inputs or returning an order the contract does not promise.</li></ul><h3>Likely follow-ups</h3><ul class="textlist">${q.follow.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><div class="notice">Correctness argument: ${esc(q.idea)} Demonstrate that claim on a small counterexample before trusting your code. Use the self-assessment control to record your current confidence.</div>`;}
function mistake(q){if(q.id==='A06')return 'Looking up a complement after insertion can reuse the current index. int subtraction can overflow.';if(q.id==='S06')return 'Choosing a unique character before counting the full input can choose one that repeats later.';if(q.id==='A03')return 'Treating duplicate maximum values as a distinct second-largest value.';if(q.id==='B02')return 'Moving the left pointer backward when an older repeat lies outside the active window.';if(q.id==='C02')return 'Calling list.remove during enhanced-for iteration instead of the owning iterator.';return /map|set|frequency/i.test(q.pattern)?'Overwriting a count with 1 on every occurrence or assuming HashMap preserves insertion order.':/pointer/i.test(q.pattern)?'Using the wrong inclusive loop boundary, or advancing only one pointer.':'Initializing accumulators incorrectly or missing the last iteration.';}
function counts(){let a=bank.map(q=>({q,e:entry(q.id)}));return {attempted:a.filter(({q,e})=>(e.draft&&e.draft!==starter(q))||['Practiced','Solved Independently','Needs Revision','Mastered'].includes(e.status)).length,solved:a.filter(({e})=>['Solved Independently','Mastered'].includes(e.status)).length,revision:a.filter(({e})=>e.status==='Needs Revision').length,seconds:a.reduce((n,{e})=>n+(e.seconds||0),0)};}
function dashboard(){let c=counts(),weak=topics.map(t=>({t,qs:bank.filter(q=>q.topic===t)})).map(x=>({...x,review:x.qs.filter(q=>entry(q.id).status==='Needs Revision').length,solved:x.qs.filter(q=>['Solved Independently','Mastered'].includes(entry(q.id).status)).length}));return `<div class="eyebrow">YOUR PRACTICE, WITH PURPOSE</div><div class="titleline"><div><h1>A little practice. A lot more confidence.</h1><p>Understand the logic today. Explain it clearly tomorrow.</p></div><div class="row"><button data-action="export">↓ Export progress</button><button data-action="import">↑ Import backup</button><input hidden id="importFile" type="file" accept="application/json"></div></div><div class="welcome"><span class="motif" aria-hidden="true">{ }</span><span class="badge" style="background:#c9dfc6">YOUR 21-DAY LEARNING PATH</span><h1 style="margin-top:15px">Make the logic click.</h1><p>One focused hour a day. Visualize the pattern, write the Java, test the boundaries, and practice saying why it works.</p><div class="row"><button class="primary" data-nav="roadmap">Continue your roadmap →</button><button data-open="S04" data-openstage="2">Explore a visualizer</button></div></div><div class="stats">${[[bank.length,'Complete practice questions','Fundamentals first'],[c.attempted,'Attempted','Drafts or recorded practice'],[c.solved,'Solved independently','Self-reported, not verified'],[c.revision,'Need revision','Added to adaptive review']].map(([v,l,s])=>`<div class="panel stat"><small>${l}</small><strong>${v}</strong><small>${s}</small></div>`).join('')}</div><div class="grid2"><section class="panel"><div class="panelhead"><h3>Your topic progress</h3><span class="badge outline">INDEPENDENT SOLVES</span></div><div class="panelbody">${weak.map(x=>`<div class="topicrow"><div class="row spread"><span>${esc(x.t)}</span><small>${x.solved} / ${x.qs.length}</small></div><div class="progress"><i style="width:${100*x.solved/x.qs.length}%"></i></div></div>`).join('')}</div></section><div class="rightstack" style="grid-template-columns:1fr"><section class="panel"><div class="panelhead"><h3>Practice signals</h3></div><div class="panelbody"><div class="row spread"><span>Active practice time</span><strong>${Math.floor(c.seconds/60)} min</strong></div><div class="row spread sectiongap"><span>Verified accuracy</span><strong>Not available</strong></div><p class="source">No code submissions have been executed by this app. Self-assessment is tracked separately from verified results.</p><h3 class="sectiongap">Topics needing attention</h3><p class="problem">${weak.filter(x=>x.review).map(x=>esc(x.t)+' ('+x.review+')').join(', ')||'Mark difficult questions “Needs Revision” to build your personal review queue.'}</p></div></section><section class="panel"><div class="panelhead"><h3>Upcoming revisions</h3></div><div class="panelbody">${reviewQueue().length?reviewQueue().slice(0,5).map(q=>`<button class="questioncard" data-open="${q.id}"><span class="qinfo"><strong>${esc(q.title)}</strong><small>${esc(entry(q.id).revisionDate||'Ready for review')}</small></span>→</button>`).join(''):'<p class="problem muted">Your review queue is clear. After a difficult attempt, mark the question for revision.</p>'}</div></section></div></div><div class="notice">${storageOK?'Progress and drafts are stored in this browser. Export a JSON backup before switching devices or clearing browser storage.':'Local storage is unavailable. Progress will last for this session only; export a backup.'} Import merges stable question IDs and keeps any additional IDs for future bank expansions.</div>`;}
function reviewQueue(){return bank.filter(q=>entry(q.id).status==='Needs Revision'||(entry(q.id).revisionDate&&entry(q.id).revisionDate<=new Date().toLocaleDateString('en-CA'))).sort((a,b)=>(entry(a.id).revisionDate||'').localeCompare(entry(b.id).revisionDate||''));}
function library(){let qs=bank.filter(q=>(view!=='bookmarks'||entry(q.id).bookmark)&&(topic==='All topics'||view==='bookmarks'||q.topic===topic)&&(difficulty==='All levels'||q.difficulty===difficulty)&&`${q.id} ${q.title} ${q.pattern} ${q.topic}`.toLowerCase().includes(search.toLowerCase()));return `<div class="titleline"><div><div class="eyebrow">CHOOSE YOUR NEXT SMALL WIN</div><h1>${view==='bookmarks'?'Your bookmarked questions':topic==='All topics'?'The question library':esc(topic)}</h1><p>Complete explanations, Java references, and interactive traces. ${qs.length} questions shown.</p></div><span class="badge outline">${bank.length} COMPLETE QUESTIONS</span></div><div class="filters"><input id="librarySearch" placeholder="Search a question or pattern…" aria-label="Filter questions by text" value="${esc(search)}"><select id="topicFilter" aria-label="Topic">${['All topics',...topics].map(t=>`<option ${topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="difficultyFilter" aria-label="Difficulty">${['All levels','Beginner','Easy','Medium','Stretch'].map(t=>`<option ${difficulty===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="questionlist">${qs.map(q=>`<button class="questioncard panel" data-open="${q.id}"><span class="qnumber">${q.id}</span><span class="qinfo"><strong>${esc(q.title)} ${entry(q.id).bookmark?'★':''}</strong><span class="qmeta"><span>${esc(q.topic)}</span><span>${esc(q.pattern)}</span><span>◷ ${q.time} min</span><span>${esc(entry(q.id).status)}</span></span></span><span class="badge ${q.difficulty==='Medium'?'yellow':''}">${q.difficulty}</span><span style="margin-left:8px">→</span></button>`).join('')||'<div class="panel empty">No matching questions. Adjust your search or filters.</div>'}</div>`;}
const plan=[['Character scans',['S01','S03']],['Two pointers',['S02','S08']],['Counts & uniqueness',['S04','S05','S06']],['String patterns',['S07','S09','S10']],['Array boundaries',['A01','A02']],['Distinct values',['A03','A04']],['Index & complement',['A05','A06']],['In-place array work',['A07','A08']],['Sets & membership',['A09','M01']],['Counts & order',['M02','M03','M04']],['Merge & search',['A10','A11']],['Collections & sorting',['A12','C01','C03','C02']],['Streams: filter & map',['T01','T03']],['Streams: group & count',['T02','N01']],['Number fundamentals',['N02','N03','N04','N05','N06']],['UI & API test data',['Q01','Q05','Q06']],['API & logs',['Q02','Q03','Q04']],['Debug & revisit',['A03','A06','C02']],['Mixed independent round',['S06','A07']],['Optional patterns & mock',['B01','B02']],['Final mock & review',['A06','Q04']]];
function roadmap(){let [name,ids]=plan[selectedDay-1],qs=ids.map(id=>bank.find(q=>q.id===id));return `<div class="titleline"><div><div class="eyebrow">60 MINUTES A DAY / 21 DAYS</div><h1>Build confidence, layer by layer.</h1><p>A guided path with review that adapts to the questions you find difficult.</p></div><span class="badge">${Object.values(days).filter(Boolean).length} / 21 days complete</span></div><div class="grid2" style="align-items:start"><div class="daygrid">${plan.map(([n,ids],i)=>`<button class="panel daycard ${selectedDay===i+1?'selected':''}" data-day="${i+1}"><span class="daynum">DAY ${String(i+1).padStart(2,'0')} ${days[i+1]?'✓':''}</span><strong>${esc(n)}</strong><small>${ids.length} exercises · 60 min</small></button>`).join('')}</div><section class="panel" style="position:sticky;top:16px"><div class="panelhead"><h3>Day ${selectedDay} · ${esc(name)}</h3></div><div class="panelbody"><p class="problem">${selectedDay===15?'Choose two number problems today. Use the remaining ones as short verbal trace exercises.':selectedDay>=19?'Use fewer hints. Say your reasoning out loud and spend the final minutes reviewing an earlier mistake.':'Focus on the pattern before speed. Use the first exercise as a guided example and the next as independent practice.'}</p><ol class="textlist"><li><strong>0–10 min · Concept review.</strong> Read Understand and Think for ${esc(qs[0].title)}. ${esc(qs[0].idea)}</li><li><strong>10–20 min · Visual demonstration.</strong> Predict the next state before pressing Next.</li><li><strong>20–45 min · Independent coding.</strong> Write one main solution. Use a second exercise as a short trace or stretch task.</li><li><strong>45–55 min · Edge-case testing.</strong> ${esc(qs[0].edges.join('; '))}.</li><li><strong>55–60 min · Explanation rehearsal.</strong> State the contract, invariant, complexity, and one mistake you avoided.</li></ol><h3>Today's exercises</h3>${qs.map((q,i)=>`<button class="questioncard" data-open="${q.id}" ${i?'data-openmode="solve"':''}><span class="qinfo"><strong>${esc(q.title)}</strong><small>${i?'Independent exercise':'Guided demonstration'}</small></span>→</button>`).join('')}<h3 class="sectiongap">Adaptive review · swap in for 10 min</h3>${reviewQueue().length?reviewQueue().slice(0,2).map(q=>`<button class="questioncard" data-open="${q.id}" data-openmode="solve"><span class="qinfo"><strong>${esc(q.title)}</strong><small>${esc(entry(q.id).revisionDate||'Review next')}</small></span>↻</button>`).join(''):'<p class="problem muted">Mark a question “Needs Revision” after a difficult attempt. It will reappear here and on your dashboard.</p>'}<label class="checkline"><input type="checkbox" id="dayComplete" ${days[selectedDay]?'checked':''}> I completed the coding, tests, and spoken explanation for this day.</label>${selectedDay===18?'<button data-nav="debug">Open debugging challenges →</button>':''}${selectedDay>=19?'<button data-nav="mock">Start a mock interview →</button>':''}</div></section></div>`;}
function timerPanel(){return `<div class="timer"><div><strong id="timerText">${sessionEnd?formatTime(Math.max(0,sessionEnd-Date.now())):sessionDone?'Session ended':'Choose a session'}</strong><small style="display:block;margin-top:5px">${locked()?'Visuals and hints stay hidden until you end or reveal.':'Review your approach using the rubric below.'}</small></div><div class="row">${!sessionEnd&&!sessionDone?`<select id="duration" aria-label="Interview duration">${[10,15,20,30].map(n=>`<option value="${n}">${n} minutes</option>`).join('')}</select><button data-action="startTimer" class="primary">Start session</button>`:sessionEnd?'<button data-action="endTimer">End & review</button>':''}<button data-action="reveal">Reveal & end session</button></div></div>${sessionDone?rubric():''}`;}
function formatTime(ms){let s=Math.ceil(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function rubric(){return `<section class="panel" style="margin-bottom:18px"><div class="panelhead"><h3>Interview debrief · manual rubric</h3><span class="badge outline">0 = missing · 1 = partial · 2 = clear</span></div><div class="panelbody rubric">${['Correctness','Edge cases','Complexity','Code quality','Explanation clarity'].map((s,i)=>`<label>${s}<select data-rubric="${i}"><option value="">Not rated</option>${[0,1,2].map(n=>`<option ${entry().rubric?.[i]===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<small>Correctness: does your locally executed code meet the contract? Edge cases: do you test boundaries? Complexity: can you justify it? Code quality: clear state and names? Explanation: contract, approach, and invariant? These scores are self-assessed and never counted as verified accuracy.</small></div></section>`;}
function mock(){return `<div class="eyebrow">THINK ALOUD / WRITE / TEST / EXPLAIN</div><h1>Your next interview starts here.</h1><p class="muted">Choose a question and session length. Start with 15 minutes; leave time to discuss edge cases.</p><section class="panel"><div class="panelbody"><label for="mockQuestion">Interview question</label><select id="mockQuestion" style="display:block;width:100%;margin:12px 0 20px">${bank.filter(q=>q.difficulty!=='Medium').map(q=>`<option value="${q.id}">${q.id} · ${esc(q.title)}</option>`).join('')}</select><p class="problem">The interview workspace opens with the problem and starter code. Solutions and visual explanations stay hidden until time expires, you end the session, or you explicitly reveal them.</p><button class="primary" data-action="openMock">Enter interview workspace →</button></div></section><h3 class="sectiongap">A practical 15-minute rhythm</h3><div class="stats">${[['2 min','Clarify input & output'],['3 min','Explain your approach'],['7 min','Write readable Java'],['3 min','Test & discuss complexity']].map(([t,d])=>`<div class="panel stat"><strong style="font-size:22px">${t}</strong><small>${d}</small></div>`).join('')}</div>`;}
const bugs=[
{title:'Off-by-one array access',code:'int max = a[0];\nfor (int i = 1; i <= a.length; i++) {\n    max = Math.max(max, a[i]);\n}\nreturn max;',test:'a = [3, 8] → expected 8; throws ArrayIndexOutOfBoundsException at i=2.',why:'Valid array indices end at length - 1. The <= condition enters the loop with i equal to length. Also clarify empty/null behavior.',fix:'Require nonempty input, initialize from a[0], then loop with i < a.length.'},
{title:'Missing null guard',code:'static boolean isBlank(String s) {\n    return s.trim().isEmpty();\n}',test:'s = null → expected true for this contract; throws NullPointerException.',why:'trim is an instance method and cannot be called through null.',fix:'return s == null || s.trim().isEmpty(); Short-circuit evaluation avoids the dereference.'},
{title:'Frequency overwritten',code:'Map<Character, Integer> counts = new HashMap<>();\nfor (char c : s.toCharArray()) {\n    counts.put(c, 1);\n}',test:'s = "aba" → expected {a=2, b=1}; produces {a=1, b=1}.',why:'put replaces an existing value. Every occurrence resets the count to one.',fix:'counts.put(c, counts.getOrDefault(c, 0) + 1);'},
{title:'Integer overflow before widening',code:'static long factorial(int n) {\n    int result = 1;\n    for (int i = 2; i <= n; i++) result *= i;\n    return result;\n}',test:'n = 13 → expected 6227020800; produces 1932053504.',why:'Multiplication happens in int before the final value is widened to long.',fix:'Use long result = 1; reject n < 0 or n > 20, or use BigInteger for arbitrary precision.'},
{title:'String identity comparison',code:'static boolean isFailed(String status) {\n    return status == "FAIL";\n}',test:'status = new String("FAIL") → expected true; returns false.',why:'== compares reference identity, so separately allocated equal strings may compare false.',fix:'return "FAIL".equals(status); This also handles null safely.'},
{title:'Concurrent list modification',code:'for (String name : names) {\n    if (name.isEmpty()) names.remove(name);\n}',test:'names = ["", "a", "b"] → should remove only blank; iteration throws ConcurrentModificationException.',why:'The list is structurally modified outside the iterator performing the enhanced-for traversal.',fix:'Use names.removeIf(name -> name == null || name.trim().isEmpty()); or iterator.remove().'},
{title:'Duplicate maximum treated as second',code:'Arrays.sort(a);\nreturn a[a.length - 2];',test:'a = [5, 9, 9] → expected second-largest distinct 5; returns 9.',why:'The second position from the end need not contain a distinct value. Arrays with fewer than two values also fail.',fix:'Track two distinct extrema, or scan backward after sorting until you find a value smaller than the maximum. Return null if none exists.'},
{title:'Binary search skips final candidate',code:'int left = 0, right = a.length - 1;\nwhile (left < right) {\n    int mid = left + (right - left) / 2;\n    if (a[mid] == target) return mid;\n    if (a[mid] < target) left = mid + 1;\n    else right = mid - 1;\n}\nreturn -1;',test:'a = [7], target = 7 → expected 0; returns -1.',why:'An inclusive range with left == right still contains one candidate.',fix:'Use while (left <= right) for this inclusive-bound algorithm.'}];
function debug(){let b=bugs[debugIndex],draft=saved.debugDrafts?.[debugIndex]||b.code;return `<div class="titleline"><div><div class="eyebrow">DEBUGGING / READ LIKE A TESTER</div><h1>Find the bug. Explain the failure.</h1><p>These challenges are intentionally incorrect. Fix them in the editor and compare your reasoning.</p></div><select id="debugSelect" aria-label="Debugging challenge">${bugs.map((b,i)=>`<option value="${i}" ${i===debugIndex?'selected':''}>${i+1}. ${esc(b.title)}</option>`).join('')}</select></div><div class="workspace"><section class="panel"><div class="panelbody"><span class="badge yellow">INTENTIONALLY BUGGY JAVA</span><h2 class="sectiongap">${esc(b.title)}</h2><pre class="reference">${highlight(b.code)}</pre><h3 class="sectiongap">Failing case</h3><div class="example">${esc(b.test)}</div><label for="bugReason" style="display:block;margin:20px 0 10px">What went wrong, and why?</label><textarea id="bugReason" style="width:100%;min-height:90px;background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:12px;color:var(--ink)" placeholder="Describe the faulty state or boundary…">${esc(saved.debugReasons?.[debugIndex]||'')}</textarea><button class="primary sectiongap" data-action="debugSubmit">Submit for manual comparison</button>${debugSubmitted?`<div class="notice"><strong>Submitted for self-review, not executed.</strong> Compare your fix with the explanation below; no pass/fail result has been recorded.</div><div class="hint"><strong>Why it fails</strong><br>${esc(b.why)}<br><strong>Repair</strong><br>${esc(b.fix)}</div>`:''}</div></section><section class="panel codepanel"><div class="panelhead"><h3>Your repaired Java</h3><span class="badge">MANUAL REVIEW</span></div><div class="editor"><pre id="codeHighlight" aria-hidden="true">${highlight(draft)}</pre><textarea id="debugEditor" aria-label="Fix the buggy Java" spellcheck="false">${esc(draft)}</textarea></div><div class="codeactions"><button data-action="resetBug">Reset buggy code</button><button data-action="copyBug">Copy repair</button></div></section></div>`;}
function researchPage(){return `<div class="eyebrow">EVIDENCE, WITH BOUNDARIES</div><h1>Recent reports & core practice.</h1><p class="muted">Research window: 5 October–5 November 2026. India-focused searches included global QA/SDET discussion.</p><div class="notice"><strong>No independently verified firsthand junior Java coding questions were established.</strong> Preparation resources are not proof a question was asked. Anonymous firsthand and shared reports remain unverified. We make no company-frequency claims. Bank questions use stable IDs and carry their own attribution.</div><section class="panel sectiongap"><div class="panelbody researchlist">${research?renderResearch(): '<p>Loading the research record…</p>'}</div></section><div class="notice">The core bank is designed for 0–2 years. Reported tasks for more experienced candidates supply context only. Publication dates are separate from interview dates; an unknown interview date remains unknown. Sources with only a crawl date are not eligible for recent-question attribution.</div>`;}
function renderResearch(){let sources=Array.isArray(research)?research:research.sources||[];return sources.map(s=>`<article><span class="badge outline">${esc(s.classification||s.source_classification||'Research context')}</span><h3 style="margin:12px 0 7px"><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a></h3><p class="source">Published: ${esc(s.publicationDate||s.publication_date||s.published_date||'not independently established')} · Interview: ${esc(s.interviewDate||s.interview_date||'not disclosed')}</p><p class="problem">${esc(s.summary||s.notes||s.caveats||s.evidence_limit||'See the source record for provenance and limitations.')}</p>${s.questions?`<ul class="textlist">${s.questions.map(q=>`<li>${esc(typeof q==='string'?q:json(q))}</li>`).join('')}</ul>`:''}</article>`).join('')+`<button data-action="downloadResearch">Download full research record</button>`;}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{let d=b.dataset.nav;if(d.startsWith('topic:')){topic=d.slice(6);search='';difficulty='All levels';navigate('library');}else{if(d==='library'){topic='All topics';search='';}navigate(d);}});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openQuestion(b.dataset.open,b.dataset.openmode||'learn',Number(b.dataset.openstage)||0));document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{if(locked()&&Number(b.dataset.stage)!==0)return;stage=Number(b.dataset.stage);playing=false;render();});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{let m=b.dataset.mode;if(m==='debug'){navigate('debug');return;}if(sessionEnd){sessionEnd=null;sessionDone=true;}mode=m;stage=m==='learn'?2:0;hints=0;revealed=false;showTraceCode=false;sessionDone=false;playing=false;render();});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);playing=false;render();});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=Number(b.dataset.day);render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));
let ed=$('#editor')||$('#debugEditor');if(ed){ed.oninput=()=>{if(ed.id==='editor'){update({draft:ed.value});}else{saved.debugDrafts??={};saved.debugDrafts[debugIndex]=ed.value;persistAll();}$('#codeHighlight').innerHTML=highlight(ed.value);};ed.onscroll=()=>{$('#codeHighlight').scrollTop=ed.scrollTop;$('#codeHighlight').scrollLeft=ed.scrollLeft;};ed.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();let a=ed.selectionStart,z=ed.selectionEnd;ed.setRangeText('    ',a,z,'end');ed.dispatchEvent(new Event('input'));}};}
if($('#sample'))$('#sample').onchange=e=>{if(e.target.value==='custom')return;try{inputIndex=Number(e.target.value);trace=execute(current(),current().samples[inputIndex]);custom=null;step=0;playing=false;render();}catch(e){toast(e.message);}};if($('#speed'))$('#speed').onchange=e=>{speed=Number(e.target.value);};if($('#timeline'))$('#timeline').oninput=e=>{step=Number(e.target.value);playing=false;render();};if($('#status'))$('#status').onchange=e=>{let status=e.target.value;update({status,revisionDate:status==='Needs Revision'?dateAfter(1):status==='Solved Independently'?dateAfter(3):status==='Mastered'?dateAfter(7):null});render();};if($('#dayComplete'))$('#dayComplete').onchange=e=>{days[selectedDay]=e.target.checked;persist();render();};if($('#topicFilter'))$('#topicFilter').onchange=e=>{topic=e.target.value;render();};if($('#difficultyFilter'))$('#difficultyFilter').onchange=e=>{difficulty=e.target.value;render();};for(let id of ['globalSearch','librarySearch'])if($('#'+id))$('#'+id).oninput=e=>{search=e.target.value;if(view!=='library'&&view!=='bookmarks'){view='library';topic='All topics';}let pos=e.target.selectionStart;render();let f=$('#librarySearch');f.focus();f.setSelectionRange(pos,pos);};if($('#debugSelect'))$('#debugSelect').onchange=e=>{debugIndex=Number(e.target.value);debugSubmitted=false;render();};if($('#bugReason'))$('#bugReason').oninput=e=>{saved.debugReasons??={};saved.debugReasons[debugIndex]=e.target.value;persistAll();};if($('#importFile'))$('#importFile').onchange=importBackup;document.querySelectorAll('[data-rubric]').forEach(e=>e.onchange=()=>{let rubric={...entry().rubric};rubric[e.dataset.rubric]=e.value===''?null:Number(e.value);update({rubric});});}
function persistAll(){try{localStorage.setItem('sdet-lab-v1',json({...saved,schemaVersion:1,progress,days,theme}));}catch{storageOK=false;}}
function dateAfter(n){let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function download(text,name,type='text/plain'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{download(text,'Solution.java');toast('Clipboard unavailable; downloaded the code instead.');}}
async function act(a){if(a==='menu'){$('.sidebar').classList.toggle('open');return;}if(a==='theme'){theme=theme==='light'?'dark':'light';persist();render();return;}if(a==='bookmark'){update({bookmark:!entry().bookmark});render();return;}if(a==='resetCode'){update({draft:starter(current())});render();toast('Starter code restored.');return;}if(a==='copy'){await copy(entry().draft||starter(current()));return;}if(a==='testHarness'){let r=await fetch('./tests/'+qid+'/TestRunner.java');if(!r.ok){toast('Harness unavailable; use the displayed reference cases.');return;}download(await r.text(),'TestRunner.java');return;}if(a==='copyReference'){copy(code(current()));return;}if(a==='download'){download(entry().draft||starter(current()),'Solution.java');return;}if(a==='hint'){if(locked())return;hints=Math.min(3,hints+1);stage=1;render();return;}if(a==='reveal'){if(mode==='timed'){sessionEnd=null;sessionDone=true;}revealed=true;stage=3;playing=false;render();return;}if(a==='traceCode'){showTraceCode=!showTraceCode;render();return;}if(a==='tests'){testOpen=!testOpen;render();return;}if(a==='play'){if(step===trace.steps.length-1)step=0;playing=!playing;render();return;}if(a==='previous'){playing=false;step=Math.max(0,step-1);render();return;}if(a==='next'){playing=false;step=Math.min(trace.steps.length-1,step+1);render();return;}if(a==='reset'){playing=false;step=0;render();return;}if(a==='custom'){customDialog();return;}if(a==='export'){download(json({schemaVersion:1,exportedAt:new Date().toISOString(),progress,days,theme,debugDrafts:saved.debugDrafts,debugReasons:saved.debugReasons}),'sdet-lab-progress.json','application/json');return;}if(a==='import'){$('#importFile').click();return;}if(a==='openMock'){openQuestion($('#mockQuestion').value,'timed',0);return;}if(a==='startTimer'){sessionEnd=Date.now()+Number($('#duration').value)*60000;sessionDone=false;render();return;}if(a==='endTimer'){sessionEnd=null;sessionDone=true;render();return;}if(a==='debugSubmit'){debugSubmitted=true;render();return;}if(a==='resetBug'){saved.debugDrafts??={};saved.debugDrafts[debugIndex]=bugs[debugIndex].code;debugSubmitted=false;persistAll();render();return;}if(a==='copyBug'){copy($('#debugEditor').value);return;}if(a==='downloadResearch')download(JSON.stringify(research,null,2),'research.json','application/json');}
function validate(q,v){const walk=x=>{if(typeof x==='number'&&(!Number.isInteger(x)||x< -2147483648||x>2147483647))throw Error('Use signed Java int values only.');if(typeof x==='string'&&(!/^[\x20-\x7E\r\n\t]*$/.test(x)||x.length>120))throw Error('Use ASCII text up to 120 characters for a matching Java char trace.');if(Array.isArray(x)){if(x.length>60)throw Error('Limit arrays to 60 items.');x.forEach(walk);}else if(x&&typeof x==='object'){if(Object.keys(x).length>60)throw Error('Limit maps to 60 entries.');Object.entries(x).forEach(([k,v])=>{walk(k);walk(v);});}};walk(v);let params=q.param.split(', ');if(q.param==='int n'&&(!Number.isInteger(v)||Math.abs(v)>1000000))throw Error('Use an integer with absolute value at most 1,000,000 for a concise trace.');if(q.param==='String s'&&typeof v!=='string')throw Error('Use a JSON string.');if(q.param==='String id'&&v!==null&&typeof v!=='string')throw Error('Use a string or null.');if(q.param==='String[] words'&&(!Array.isArray(v)||v.length!==2||v.some(x=>typeof x!=='string')))throw Error('Use exactly two strings.');if(q.param.startsWith('List<String>')&&(!Array.isArray(v)||v.some(x=>x!==null&&typeof x!=='string')))throw Error('Use a list of strings (or null entries where supported).');if(q.param==='List<Integer> values'&&(!Array.isArray(v)||v.some(x=>!Number.isInteger(x))))throw Error('Use a list of integers.');if(q.param==='int[] a'||q.param==='int[] codes'){if(!Array.isArray(v)||v.some(x=>!Number.isInteger(x)))throw Error('Use an integer array.');}if((q.param==='Map<String, Integer> values'||q.param==='Map<String, Integer> counts')&&(!v||Array.isArray(v)||typeof v!=='object'||Object.values(v).some(x=>!Number.isInteger(x))))throw Error('Use an object with integer values.');if(q.param.includes(', int target')||q.param.includes(', int k')||q.param==='int[] a, int[] b'){let keys=q.param==='int[] a, int[] b'?['a','b']:['a',q.param.includes('target')?'target':'k'];if(!v||typeof v!=='object'||keys.some(k=>!Object.hasOwn(v,k))||!Array.isArray(v.a)||v.a.some(x=>!Number.isInteger(x)))throw Error('Use the same object shape as the sample.');if(keys[1]==='b'){if(!Array.isArray(v.b)||v.b.some(x=>!Number.isInteger(x)))throw Error('b must be an integer array.');}else if(!Number.isInteger(v[keys[1]]))throw Error('target or k must be an integer.');}if(q.id==='A05'&&(new Set(v).size!==v.length||v.some(x=>x<0||x>v.length)))throw Error('Missing-number input must contain distinct integers from 0 through n.');if(['A10','A11'].includes(q.id)){let arrays=q.id==='A10'?[v.a,v.b]:[v.a];if(arrays.some(a=>a.some((x,i)=>i&&a[i-1]>x)))throw Error('Binary search and merge require ascending sorted arrays.');}if(q.id==='C03'&&(!Array.isArray(v)||v.some(x=>!x||typeof x.name!=='string'||!Number.isInteger(x.durationMs))))throw Error('Use test-result objects with name and integer durationMs.');if(q.id==='Q04'){if(!v||typeof v!=='object'||!v.expected||!v.actual||[v.expected,v.actual].some(m=>Array.isArray(m)||typeof m!=='object'||Object.values(m).some(x=>x!==null&&typeof x!=='string')))throw Error('Use expected and actual objects with string or null values.');}if(q.id==='N04'&&v>60)throw Error('Limit FizzBuzz to 60 values in the visualizer.');}
function customDialog(){playing=false;let d=document.createElement('dialog');d.style.cssText='width:min(540px,92vw);padding:25px;border:1px solid var(--border);border-radius:12px;background:var(--card);color:var(--ink)';d.innerHTML=`<form id="customForm"><h2>Try your own input</h2><p class="problem">Use the same JSON shape as the sample. Visual traces are limited to ASCII strings and small arrays.</p><textarea id="customValue" aria-label="Custom JSON input" style="width:100%;height:120px;padding:12px;background:var(--bg);color:var(--ink);border:1px solid var(--border);border-radius:7px">${esc(json(custom===null?current().samples[inputIndex]:custom))}</textarea><p id="customError" role="alert" style="color:#b2463b;font-size:12px"></p><div class="row"><button class="primary" type="submit">Build reference trace</button><button id="closeCustom" type="button">Cancel</button></div></form>`;document.body.append(d);d.showModal();$('#closeCustom').onclick=()=>d.close();d.onclose=()=>d.remove();$('#customForm').onsubmit=e=>{e.preventDefault();try{let v=JSON.parse($('#customValue').value);validate(current(),v);let t=execute(current(),v);custom=v;trace=t;step=0;d.close();render();}catch(e){$('#customError').textContent=e.message;}};}
async function importBackup(e){try{let f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Backup is too large (maximum 3 MB).');let data=JSON.parse(await f.text());if(data.schemaVersion!==1||!data.progress||typeof data.progress!=='object'||Array.isArray(data.progress))throw Error('Use an exported version 1 lab backup.');let clean={};for(let [id,p]of Object.entries(data.progress)){if(!/^[A-Z][0-9]{2}$/.test(id)||!p||typeof p!=='object'||!statuses.includes(p.status))throw Error('Invalid question progress entry.');clean[id]={status:p.status,seconds:Math.max(0,Number(p.seconds)||0),bookmark:!!p.bookmark,draft:typeof p.draft==='string'?p.draft.slice(0,100000):undefined,revisionDate:/^\d{4}-\d{2}-\d{2}$/.test(p.revisionDate)?p.revisionDate:null,rubric:p.rubric&&typeof p.rubric==='object'?p.rubric:undefined};}progress={...progress,...clean};if(data.days&&typeof data.days==='object')for(let i=1;i<=21;i++)if(typeof data.days[i]==='boolean')days[i]=data.days[i];persist();render();toast('Backup merged by stable question ID.');}catch(e){toast('Import failed: '+e.message);}}
let lastTick=Date.now(),animationBudget=0;setInterval(()=>{let now=Date.now(),delta=Math.min(1500,now-lastTick);lastTick=now;if(document.visibilityState==='visible'&&document.hasFocus()&&view==='lab'){update({seconds:(entry().seconds||0)+delta/1000});}if(sessionEnd){if(now>=sessionEnd){sessionEnd=null;sessionDone=true;playing=false;render();toast('Interview time is up. Review your approach.');}else if($('#timerText'))$('#timerText').textContent=formatTime(sessionEnd-now);}if(playing&&view==='lab'&&stage===2&&document.visibilityState==='visible'){animationBudget+=delta;if(animationBudget>=1000/speed){animationBudget=0;if(step<trace.steps.length-1)step++;if(step===trace.steps.length-1)playing=false;render();}}},250);
fetch('./research.json').then(r=>r.json()).then(r=>{research=r;const mapping={S04:'prep-java-20261026',S06:'prep-java-20261026',S09:'prep-java-20261026',S10:'prep-java-20261026',A03:'prep-java-20261026',A05:'prep-java-20261026',M01:'prep-java-20261026',M04:'prep-java-20261026',B01:'prep-java-20261026',Q02:'prep-qa-20261025',Q03:'prep-qa-20261025',Q04:'prep-qa-20261025'};for(let q of bank){let s=(r.sources||[]).find(s=>s.id===mapping[q.id]);if(s){q.source='Recent preparation resource';q.url=s.url;q.date=s.publicationDate;}}if(view==='research'||view==='lab')render();}).catch(()=>{research={sources:[]};if(view==='research')render();});
window.addEventListener('beforeunload',persistAll);render();
